class Solution {
  private static final int BITS = 17;
  private int[] zero, one, count;
  private int nodes = 1;

  public int[] maxGeneticDifference(int[] parents, int[][] queries) {
    int n = parents.length, root = 0;
    int[] childHead = new int[n], childNext = new int[n];
    Arrays.fill(childHead, -1);
    for (int i = 0; i < n; i++) {
      if (parents[i] == -1) root = i;
      else {
        childNext[i] = childHead[parents[i]];
        childHead[parents[i]] = i;
      }
    }
    int[] queryHead = new int[n], queryNext = new int[queries.length];
    Arrays.fill(queryHead, -1);
    for (int q = 0; q < queries.length; q++) {
      queryNext[q] = queryHead[queries[q][0]];
      queryHead[queries[q][0]] = q;
    }
    int size = (n + 1) * (BITS + 2) + 2;
    zero = new int[size];
    one = new int[size];
    count = new int[size];
    int[] answer = new int[queries.length];
    int[] stack = new int[n], cursor = childHead.clone();
    int top = 0;
    stack[top++] = root;
    enter(root, queries, queryHead, queryNext, answer);
    while (top > 0) {
      int u = stack[top - 1];
      if (cursor[u] != -1) {
        int v = cursor[u];
        cursor[u] = childNext[v];
        enter(v, queries, queryHead, queryNext, answer);
        stack[top++] = v;
      } else {
        update(u, -1);
        top--;
      }
    }
    return answer;
  }

  private void enter(int node, int[][] queries, int[] queryHead, int[] queryNext, int[] answer) {
    update(node, 1);
    for (int q = queryHead[node]; q != -1; q = queryNext[q]) answer[q] = maxXor(queries[q][1]);
  }

  private void update(int value, int delta) {
    int node = 0;
    for (int bit = BITS; bit >= 0; bit--) {
      boolean set = ((value >> bit) & 1) == 1;
      int next = set ? one[node] : zero[node];
      if (next == 0) {
        next = nodes++;
        if (set) one[node] = next;
        else zero[node] = next;
      }
      node = next;
      count[node] += delta;
    }
  }

  private int maxXor(int value) {
    int node = 0, result = 0;
    for (int bit = BITS; bit >= 0; bit--) {
      boolean set = ((value >> bit) & 1) == 1;
      int want = set ? zero[node] : one[node];
      if (want != 0 && count[want] > 0) {
        result |= 1 << bit;
        node = want;
      } else {
        node = set ? one[node] : zero[node];
      }
    }
    return result;
  }
}
